import { BoxGeometry, PlaneGeometry, MeshPhysicalNodeMaterial, Group, DirectionalLight, AmbientLight } from 'three/webgpu';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, Vector3 } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  const group = new Group();

  // Root container for motion and offset effects
  const contentContainer = new Group();
  group.add(contentContainer);

  // 1. STAGE & BACKDROP FRAME
  // Local card body
  const cardWidth = 2.4;
  const cardHeight = 2.4;
  const cardDepth = 0.15;

  const cardGeo = new BoxGeometry(cardWidth, cardHeight, cardDepth);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: colors.surface,
    roughness: 0.55,
    metalness: 0.4,
    clearcoat: 0.1,
    envMapIntensity: 1.0,
  });

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, -cardDepth / 2);
  contentContainer.add(cardMesh);

  // Red accent indicator (signal red #ff2a38)
  const tagGeo = new BoxGeometry(0.12, 0.12, 0.05);
  const tagMat = new MeshPhysicalNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.2,
    roughness: 0.2,
    metalness: 0.8
  });
  const tagMesh = new Mesh(tagGeo, tagMat);
  tagMesh.position.set(cardWidth / 2 - 0.2, cardHeight / 2 - 0.2, 0.01);
  contentContainer.add(tagMesh);

  // Minimal sub-shadow on the card surface matching the gear
  const shadowGeo = new PlaneGeometry(1.6, 1.6);
  const shadowMat = new MeshPhysicalNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.65,
    roughness: 1.0,
    metalness: 0.0,
    depthWrite: false
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, 0, 0.01);
  contentContainer.add(shadowMesh);

  // Local Rim Light to project accent hue
  const rimLight = new DirectionalLight(colors.accent, 1.5);
  rimLight.position.set(-2, 2, 2);
  contentContainer.add(rimLight);

  // 2. HERO MESH LOADING
  let loadedMesh = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      loadedMesh = gltf.scene;

      // Fit and scale mesh to card
      const box = new THREE.Box3().setFromObject(loadedMesh);
      const size = box.getSize(new Vector3());
      const maxDim = Math.max(size.x, size.y, size.z);
      const targetScale = 1.6 / maxDim;

      loadedMesh.scale.setScalar(targetScale);

      // Center geometry pivot
      const center = box.getCenter(new Vector3());
      loadedMesh.position.sub(center.multiplyScalar(targetScale));
      loadedMesh.position.z += 0.2; // project forward

      // Enhanced machined-metal PBR styling
      loadedMesh.traverse((child) => {
        if (child.isMesh) {
          child.material = new MeshPhysicalNodeMaterial({
            color: colors.paper,
            roughness: 0.15,
            metalness: 0.95,
            clearcoat: 0.3,
            clearcoatRoughness: 0.1,
            envMapIntensity: 1.5,
          });
          child.castShadow = true;
          child.receiveShadow = true;
        }
      });

      contentContainer.add(loadedMesh);

      // Settle animation on load
      gsap.fromTo(loadedMesh.rotation, 
        { z: -1 }, 
        { z: 0.2, duration: 1.6, ease: "power4.out" }
      );
      gsap.fromTo(loadedMesh.scale, 
        { x: 0.01, y: 0.01, z: 0.01 }, 
        { x: targetScale, y: targetScale, z: targetScale, duration: 1.2, ease: "power3.out" }
      );
    });
  }

  // 3. INTERACTIVE BEHAVIORS
  let hoverTimeline = null;

  const onPointerOver = () => {
    // Subtle rise-in hover effect (0.15 units forward & slightly up)
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(contentContainer.position, {
      y: 0.12,
      z: 0.15,
      duration: 0.4,
      ease: "power2.out"
    });
    if (loadedMesh) {
      hoverTimeline.to(loadedMesh.rotation, {
        z: "+=0.3",
        duration: 0.6,
        ease: "power2.out"
      }, 0);
    }
  };

  const onPointerOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(contentContainer.position, {
      x: 0,
      y: 0,
      z: 0,
      duration: 0.5,
      ease: "power2.out"
    });
    if (loadedMesh) {
      hoverTimeline.to(loadedMesh.rotation, {
        z: 0.2,
        duration: 0.7,
        ease: "power2.out"
      }, 0);
    }
  };

  const onPointerDown = () => {
    // Press down squeeze
    gsap.to(contentContainer.scale, {
      x: 0.94,
      y: 0.94,
      z: 0.94,
      duration: 0.1,
      ease: "power1.out"
    });
  };

  const onPointerUp = () => {
    gsap.to(contentContainer.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.4,
      ease: "back.out(2)"
    });
    // Emit navigation select
    ctx.emit("hub-features.select", { id: config.id });
  };

  // Attach handlers
  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
  };

  // 4. APPLY CLINEMATIC PRIMITIVES
  const primitives = [];
  if (ctx.primitives) {
    if (ctx.primitives["parallax-scroll"]) {
      primitives.push(ctx.primitives["parallax-scroll"](contentContainer, { intensity: 0.4 }));
    }
    if (ctx.primitives["magnetic-cursor"]) {
      primitives.push(ctx.primitives["magnetic-cursor"](contentContainer, { radius: 1.2, strength: 0.35 }));
    }
  }

  // 5. CLEANUP HANDLER
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    primitives.forEach((p) => {
      if (typeof p.cleanup === "function") p.cleanup();
    });
    cardGeo.dispose();
    cardMat.dispose();
    tagGeo.dispose();
    tagMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return group;
}
